Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Comet Dodger</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     background: #2f3e3a;
14|     overflow: hidden;
15|     touch-action: none;
16|   }
17|   canvas {
18|     display: block;
19|     width: 100vw;
20|     height: 100dvh;
21|     background: #2f3e3a;
22|   }
23| </style>
24| </head>
25| <body>
26| <canvas id="game"></canvas>
27| <script>
28| const CARTRIDGE = {
29|   send(type, payload = {}) {
30|     window.parent.postMessage(
31|       { source: "cartridge", v: 1, type, payload },
32|       "*",
33|     );
34|   },
35| };
36| </script>
37| <script>
38| (function(){
39|   const canvas = document.getElementById('game');
40|   const ctx = canvas.getContext('2d');
41| 
42|   const COL_SLATE = '#2f3e3a';
43|   const COL_CHALK = '#eeeae0';
44|   const COL_ACCENT = '#f2c14e';
45|   const COL_SECOND = '#8fc1e3';
46| 
47|   let dpr = Math.max(1, window.devicePixelRatio || 1);
48|   let W = 0, H = 0;
49| 
50|   function resize() {
51|     W = window.innerWidth;
52|     H = window.innerHeight;
53|     dpr = Math.max(1, window.devicePixelRatio || 1);
54|     canvas.width = Math.floor(W * dpr);
55|     canvas.height = Math.floor(H * dpr);
56|     canvas.style.width = W + 'px';
57|     canvas.style.height = H + 'px';
58|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
59|   }
60|   window.addEventListener('resize', resize);
61|   resize();
62| 
63|   // ---------- state ----------
64|   let last = 0;
65|   let running = false;
66|   let paused = false;
67|   let started = false;
68|   let score = 0;
69|   let scoreSent = -1;
70|   let stateName = 'title'; // title, playing, dead
71| 
72|   let elapsed = 0;
73|   let speedMult = 1;
74|   let idleTimer = 0;
75|   let hasMoved = false;
76| 
77|   let ship = { x: 0, y: 0, target: 0, r: 22 };
78|   let comets = [];
79|   let spawnTimer = 0;
80|   let spawnInterval = 1.4;
81| 
82|   let smudges = [];
83| 
84|   function makeSmudges() {
85|     smudges = [];
86|     for (let i = 0; i < 5; i++) {
87|       smudges.push({
88|         x: Math.random() * W,
89|         y: Math.random() * H,
90|         r: 80 + Math.random() * 160,
91|         a: 0.02 + Math.random() * 0.03
92|       });
93|     }
94|   }
95| 
96|   function resetGameState() {
97|     score = 0;
98|     scoreSent = -1;
99|     elapsed = 0;
100|     speedMult = 1;
101|     comets = [];
102|     spawnTimer = 0;
103|     spawnInterval = 1.4;
104|     ship.x = W / 2;
105|     ship.y = H - 100;
106|     ship.target = ship.x;
107|     idleTimer = 0;
108|     hasMoved = false;
109|     makeSmudges();
110|   }
111| 
112|   function backToTitle() {
113|     running = false;
114|     paused = false;
115|     started = false;
116|     stateName = 'title';
117|     resetGameState();
118|   }
119| 
120|   resetGameState();
121| 
122|   // ---------- input ----------
123|   let held = false;
124| 
125|   function toCanvas(evt) {
126|     const rect = canvas.getBoundingClientRect();
127|     return {
128|       x: (evt.clientX - rect.left),
129|       y: (evt.clientY - rect.top)
130|     };
131|   }
132| 
133|   function startPlay() {
134|     if (started) return;
135|     started = true;
136|     running = true;
137|     paused = false;
138|     stateName = 'playing';
139|     resetGameState();
140|     CARTRIDGE.send('start');
141|   }
142| 
143|   canvas.addEventListener('pointerdown', (evt) => {
144|     if (stateName === 'title' || stateName === 'dead') {
145|       startPlay();
146|     }
147|     const p = toCanvas(evt);
148|     ship.target = p.x;
149|     held = true;
150|     hasMoved = true;
151|     try { canvas.setPointerCapture(evt.pointerId); } catch(e) {}
152|   });
153|   canvas.addEventListener('pointermove', (evt) => {
154|     if (held) {
155|       const p = toCanvas(evt);
156|       ship.target = p.x;
157|       hasMoved = true;
158|     }
159|   });
160|   function release() { held = false; }
161|   canvas.addEventListener('pointerup', release);
162|   canvas.addEventListener('pointercancel', release);
163| 
164|   // ---------- host messages ----------
165|   window.addEventListener('message', (event) => {
166|     const data = event.data;
167|     if (!data || data.source !== 'cartridge-host') return;
168|     if (data.type === 'pause') paused = true;
169|     if (data.type === 'resume') paused = false;
170|     if (data.type === 'reset') backToTitle();
171|   });
172| 
173|   // ---------- chalk drawing helpers ----------
174|   function wobble(seed) {
175|     return Math.sin(seed * 12.9898) * 0.6;
176|   }
177| 
178|   function chalkLine(x1, y1, x2, y2, color, width) {
179|     ctx.lineCap = 'round';
180|     ctx.lineJoin = 'round';
181|     for (let pass = 0; pass < 2; pass++) {
182|       const off = pass === 0 ? 0 : 1;
183|       const alpha = pass === 0 ? 0.9 : 0.35;
184|       ctx.strokeStyle = color;
185|       ctx.globalAlpha = alpha;
186|       ctx.lineWidth = width;
187|       ctx.beginPath();
188|       ctx.moveTo(x1 + off, y1 + off * 0.5);
189|       ctx.lineTo(x2 + off, y2 + off * 0.5);
190|       ctx.stroke();
191|     }
192|     ctx.globalAlpha = 1;
193|   }
194| 
195|   function chalkCircle(cx, cy, r, color, width, segs) {
196|     segs = segs || 20;
197|     for (let pass = 0; pass < 2; pass++) {
198|       const off = pass === 0 ? 0 : 1;
199|       const alpha = pass === 0 ? 0.9 : 0.3;
200|       ctx.strokeStyle = color;
201|       ctx.globalAlpha = alpha;
202|       ctx.lineWidth = width;
203|       ctx.lineCap = 'round';
204|       ctx.beginPath();
205|       for (let i = 0; i <= segs; i++) {
206|         const t = (i / segs) * Math.PI * 2;
207|         const wob = wobble(i + cx + cy) * 1.2;
208|         const x = cx + Math.cos(t) * r + wob + off;
209|         const y = cy + Math.sin(t) * r + wob + off * 0.5;
210|         if (i === 0) ctx.moveTo(x, y);
211|         else ctx.lineTo(x, y);
212|       }
213|       ctx.stroke();
214|     }
215|     ctx.globalAlpha = 1;
216|   }
217| 
218|   function hatchCircle(cx, cy, r, color, count) {
219|     ctx.strokeStyle = color;
220|     ctx.lineWidth = 2;
221|     ctx.globalAlpha = 0.5;
222|     for (let i = 0; i < count; i++) {
223|       const ang = (i / count) * Math.PI * 2 + wobble(i) * 0.1;
224|       const inner = r * 0.3;
225|       const outer = r * 0.85;
226|       const x1 = cx + Math.cos(ang) * inner;
227|       const y1 = cy + Math.sin(ang) * inner;
228|       const x2 = cx + Math.cos(ang) * outer;
229|       const y2 = cy + Math.sin(ang) * outer;
230|       ctx.beginPath();
231|       ctx.moveTo(x1, y1);
232|       ctx.lineTo(x2, y2);
233|       ctx.stroke();
234|     }
235|     ctx.globalAlpha = 1;
236|   }
237| 
238|   function drawSmudges() {
239|     for (const s of smudges) {
240|       ctx.beginPath();
241|       ctx.fillStyle = COL_CHALK;
242|       ctx.globalAlpha = s.a;
243|       ctx.ellipse(s.x, s.y, s.r, s.r * 0.6, 0, 0, Math.PI * 2);
244|       ctx.fill();
245|       ctx.globalAlpha = 1;
246|     }
247|   }
248| 
249|   // ---------- ship ----------
250|   function drawShip() {
251|     const x = ship.x, y = ship.y;
252|     // body triangle-ish
253|     chalkLine(x, y - 26, x - 18, y + 18, COL_CHALK, 4);
254|     chalkLine(x - 18, y + 18, x + 18, y + 18, COL_CHALK, 4);
255|     chalkLine(x + 18, y + 18, x, y - 26, COL_CHALK, 4);
256|     // cockpit
257|     chalkCircle(x, y - 2, 7, COL_SECOND, 3, 12);
258|     // flame flicker
259|     const flick = 6 + Math.sin(elapsed * 20) * 3;
260|     chalkLine(x - 8, y + 18, x, y + 18 + flick, COL_ACCENT, 3);
261|     chalkLine(x + 8, y + 18, x, y + 18 + flick, COL_ACCENT, 3);
262|   }
263| 
264|   // ---------- comets ----------
265|   function spawnComet() {
266|     const r = 16 + Math.random() * 18;
267|     const x = r + Math.random() * (W - r * 2);
268|     const speed = (120 + Math.random() * 80) * speedMult;
269|     comets.push({ x, y: -r - 20, r, speed, rot: Math.random() * Math.PI });
270|   }
271| 
272|   function drawComet(c) {
273|     ctx.save();
274|     ctx.translate(c.x, c.y);
275|     ctx.rotate(c.rot);
276|     chalkCircle(0, 0, c.r, COL_CHALK, 3, 14);
277|     hatchCircle(0, 0, c.r, COL_SECOND, 8);
278|     ctx.restore();
279|     // trailing streak
280|     chalkLine(c.x, c.y - c.r, c.x - c.r * 0.5, c.y - c.r - 20, COL_ACCENT, 2);
281|   }
282| 
283|   // ---------- game logic ----------
284|   function advance(dt) {
285|     elapsed += dt;
286|     speedMult = 1 + elapsed / 25;
287| 
288|     // ease ship toward target
289|     const dx = ship.target - ship.x;
290|     ship.x += dx * Math.min(1, dt * 10);
291|     ship.x = Math.max(ship.r, Math.min(W - ship.r, ship.x));
292| 
293|     if (!hasMoved) {
294|       idleTimer += dt;
295|     }
296| 
297|     // spawn
298|     spawnTimer -= dt;
299|     if (spawnTimer <= 0) {
300|       // fairness: don't spawn near player's opening lane during first 2s
301|       if (elapsed > 1.8) {
302|         spawnComet();
303|       }
304|       spawnInterval = Math.max(0.45, 1.4 - elapsed * 0.02);
305|       spawnTimer = spawnInterval;
306|     }
307| 
308|     for (const c of comets) {
309|       c.y += c.speed * dt;
310|       c.rot += dt * 1.2;
311|     }
312|     comets = comets.filter(c => c.y - c.r < H + 40);
313| 
314|     // score by survival time
315|     score = Math.floor(elapsed * 10);
316|     if (score !== scoreSent) {
317|       scoreSent = score;
318|       CARTRIDGE.send('score', { value: score });
319|     }
320|   }
321| 
322|   function collide() {
323|     for (const c of comets) {
324|       const dx = c.x - ship.x;
325|       const dy = c.y - ship.y;
326|       const dist = Math.sqrt(dx * dx + dy * dy);
327|       if (dist < c.r + ship.r * 0.7) {
328|         crash();
329|         return;
330|       }
331|     }
332|   }
333| 
334|   function crash() {
335|     running = false;
336|     stateName = 'dead';
337|     CARTRIDGE.send('end', { reason: 'lose', value: score });
338|   }
339| 
340|   // ---------- drawing ----------
341|   function drawBackground() {
342|     ctx.fillStyle = COL_SLATE;
343|     ctx.fillRect(0, 0, W, H);
344|     drawSmudges();
345|     // border frame like chalk edge
346|     chalkLine(10, 10, W - 10, 10, COL_CHALK, 3);
347|     chalkLine(10, H - 10, W - 10, H - 10, COL_CHALK, 3);
348|     chalkLine(10, 10, 10, H - 10, COL_CHALK, 3);
349|     chalkLine(W - 10, 10, W - 10, H - 10, COL_CHALK, 3);
350|   }
351| 
352|   function drawTitle() {
353|     ctx.fillStyle = COL_CHALK;
354|     ctx.textAlign = 'center';
355|     ctx.font = 'bold 42px system-ui, sans-serif';
356|     ctx.globalAlpha = 0.9;
357|     ctx.fillText('Comet Dodger', W / 2, H / 2 - 60);
358|     ctx.globalAlpha = 1;
359|     ctx.font = '20px system-ui, sans-serif';
360|     ctx.fillStyle = COL_SECOND;
361|     const pulse = 0.6 + Math.sin(elapsed * 3) * 0.4;
362|     ctx.globalAlpha = pulse;
363|     ctx.fillText('Drag anywhere to steer and start', W / 2, H / 2);
364|     ctx.globalAlpha = 1;
365| 
366|     // drifting demo comet
367|     const dcx = W / 2 + Math.sin(elapsed) * 60;
368|     const dcy = H / 2 + 80 + Math.cos(elapsed * 0.7) * 10;
369|     chalkCircle(dcx, dcy, 14, COL_CHALK, 3, 12);
370|     hatchCircle(dcx, dcy, 14, COL_SECOND, 6);
371|   }
372| 
373|   function drawDead() {
374|     ctx.fillStyle = COL_CHALK;
375|     ctx.textAlign = 'center';
376|     ctx.font = 'bold 36px system-ui, sans-serif';
377|     ctx.fillText('Crashed!', W / 2, H / 2 - 40);
378|     ctx.font = '22px system-ui, sans-serif';
379|     ctx.fillStyle = COL_ACCENT;
380|     ctx.fillText('Score: ' + score, W / 2, H / 2);
381|     ctx.fillStyle = COL_SECOND;
382|     const pulse = 0.6 + Math.sin(elapsed * 3) * 0.4;
383|     ctx.globalAlpha = pulse;
384|     ctx.font = '18px system-ui, sans-serif';
385|     ctx.fillText('Tap to try again', W / 2, H / 2 + 40);
386|     ctx.globalAlpha = 1;
387|   }
388| 
389|   function drawHUD() {
390|     ctx.fillStyle = COL_CHALK;
391|     ctx.textAlign = 'left';
392|     ctx.font = '20px system-ui, sans-serif';
393|     ctx.globalAlpha = 0.9;
394|     ctx.fillText('Score: ' + score, 24, 42);
395|     ctx.globalAlpha = 1;
396|   }
397| 
398|   function draw() {
399|     drawBackground();
400| 
401|     if (stateName === 'title') {
402|       drawTitle();
403|     } else if (stateName === 'playing') {
404|       for (const c of comets) drawComet(c);
405|       drawShip();
406|       drawHUD();
407|       if (paused) {
408|         ctx.fillStyle = COL_CHALK;
409|         ctx.textAlign = 'center';
410|         ctx.font = 'bold 32px system-ui, sans-serif';
411|         ctx.fillText('Paused', W / 2, H / 2);
412|       }
413|     } else if (stateName === 'dead') {
414|       for (const c of comets) drawComet(c);
415|       drawShip();
416|       drawDead();
417|     }
418|   }
419| 
420|   // ---------- main loop ----------
421|   function frame(now) {
422|     if (!last) last = now;
423|     const dt = Math.min((now - last) / 1000, 0.05);
424|     last = now;
425|     if (running && !paused && stateName === 'playing') {
426|       advance(dt);
427|       collide();
428|     } else if (stateName === 'title' || stateName === 'dead') {
429|       elapsed += dt; // keep decorative motion alive
430|     }
431|     draw();
432|     requestAnimationFrame(frame);
433|   }
434| 
435|   requestAnimationFrame((t) => {
436|     last = t;
437|     draw();
438|     CARTRIDGE.send('boot', { title: 'Comet Dodger', gameType: 'arcade-run', lang: 'en' });
439|     requestAnimationFrame(frame);
440|   });
441| })();
442| </script>
443| </body>
444| </html>
445|

